      "찰리가 직접 모든 투숙객을 관리하는 건 가능한가":["찰리가 손님을 전부 직접 챙기는 건 무리 아닐까?","찰리가 모든 투숙객을 직접 챙기는 건 무리가 아닐까요?","찰리가 모든 손님을 직접 돌보는 건 무리가 아니겠소?"],
      "호텔이 정말 성공하면 그다음에는 무엇을 해야 하는가":["호텔이 진짜 자리 잡으면 그다음엔 뭘 하지?","호텔이 정말 자리 잡으면 그다음에는 뭘 해야 할까요?","호텔이 자리를 잡고 나면 그다음은 무엇을 해야 할까?"],
