      "천국의 시민들은 구원된 죄인을 받아들일 준비가 되어 있는가":["천국 쪽에서 구원된 죄인을 진짜 반길까?","천국 사람들이 구원된 죄인을 정말 받아들일 준비가 됐을까요?","천국 사람들이 구원된 죄인을 정말 반길 준비가 되었을까?"],
      "진짜 구원을 원하는 사람과 천국만 원하는 사람을 구분하는 방법":["호텔에 오는 사람이 진짜 변하고 싶은 건지는 어떻게 알아보지?","호텔에 오는 사람이 정말 변하고 싶은 건지는 어떻게 구분할까요?","호텔에 오는 이가 진정 변하려는지는 어찌 알아볼까?"],
      "영혼을 계약으로 소유한다는 것은 정확히 무엇을 의미하는가":["영혼 계약이란 게 결국 어디까지 묶는 걸까?","영혼 계약은 실제로 어디까지 상대를 묶는 걸까요?","영혼 계약이란 것이 대체 어디까지 사람을 묶는 걸까?"],
