  const characterStarter=(c,t,high,key)=>{
    const core=topicStarterCore(t,c.id+"::"+t.id+"::core::"+(high?"h":"l"));
    const row=CHARACTER_START_STYLE[c.id]||[x=>x];
    const base=hash(c.id+"::"+t.id+"::starter")%row.length;
    const index=(base+(high&&row.length>1?1:0))%row.length;
    return row[index](core);
  };

  const startRemark=(c,t,high,key)=>{
    const personal=isPersonalFor(c,t);

    if(c.id==="lucifer-morningstar"&&/가족|찰리|릴리스/.test(t.title))return pick([
      "가족 얘기만 나오면 다들 갑자기 전문가가 되더라. 신기하지?",
      "가족은 참 편리한 단어야. 같은 말로 칭찬도 하고 싸움도 시작할 수 있거든.",
      "가족 문제 해결 매뉴얼이 있으면 왕실 예산으로 백 권쯤 사고 싶네."
    ],key);

    if(personal&&c.id==="alastor"){
      const core=topicStarterCore(t,key+"p");
      return pick([
        core+" 사람들은 이런 때 유난히 남의 사정을 알고 싶어 하더군요.",
        core+" 재미있는 건 답보다 그걸 굳이 캐내려는 쪽이지요.",
        core+" 이런 화제는 질문하는 사람의 태도도 꽤 잘 보여준답니다."
      ],key);
    }

    if(personal&&c.id==="loona")return pick([
      "그냥 생각난 건데 이상한 의미 붙이지 마. "+topicStarterCore(t,key+"p"),
      "별거 아니니까 표정 그렇게 하지 말고. "+topicStarterCore(t,key+"p2")
    ],key);

    if(personal&&c.id==="blitzo")return pick([
      "감정 상담 시작하려는 거 아니니까 그냥 들어. "+topicStarterCore(t,key+"p"),
      "의미 부여는 금지. "+topicStarterCore(t,key+"p2")
    ],key);

    if(personal&&c.id==="stolas")return pick([
      "조금 마음에 걸린 건 맞지만 너무 심각하게 들을 필요는 없어요. "+topicStarterCore(t,key+"p"),
      "그냥 생각이 난 것뿐이에요. "+topicStarterCore(t,key+"p2")
    ],key);

    return characterStarter(c,t,high,key);
  };

