      probe:(x,h)=>h?"조금만 더? 좋아. "+x+"이 제일 걸려. 근데 이걸 내 인생 다큐로 만들 생각은 접어둬.":"왜냐고? "+x+" 보면 대충 답 나오잖아. 나머지는 굳이 벗겨볼 필요 없고.",
      joke:(x,h)=>h?"하, 그래. 그쪽이 낫다. 너무 진지해지면 메이크업 무너져. "+x+" 정도만 챙기자고.":"좋아, 자기. 그 반응이면 분위기 안 죽네.",
      shift:(x,h)=>h?"좋아, 컷. 이쯤이면 충분히 말했어. 다음엔 좀 더 예쁜 얘기 하자.":"응, 다음. 이건 여기까지."
