      probe:(x,h)=>h?"더 말하자면 "+x+" 때문이야. 근데 그걸 설명한다고 사람이 달라지진 않아. 그냥 보면 돼.":"왜냐고? "+x+"이 제일 솔직하니까. 됐지?",
