      probe:(x,h)=>h?"더 듣고 싶다면 이거다. "+x+"을 안 보고 결정하면 결국 누군가 책임을 피한다. 난 그걸 못 봐준다.":"이유는 "+x+"이다. 그걸 빼면 전부 핑계가 된다.",
      joke:(x,h)=>h?"흥. 농담은 해도 된다. 그래도 "+x+"만큼은 장난으로 넘기지 마.":"좋아. 웃을 건 웃어. 할 일은 하면 된다.",
