      probe:(x,h)=>h?"조금 더? "+x+" 때문이야. 그 이상은 진짜 안 말해.":"왜냐면 "+x+"이 제일 확실하니까. 됐지?",
      joke:(x,h)=>h?"…그건 좀 낫네. 그래도 "+x+"은 챙겨. 나중에 귀찮아지기 싫으면.":"그래. 그 정도면 안 짜증나.",
