      joke:(x,h)=>h?"…그 정도 농담은 괜찮네. 그래도 "+x+"은 그냥 넘기진 않을 거야.":"응. 그 정도면 안 피곤해.",
      shift:(x,h)=>h?"좋아. 여기서 끝내자. 음악 얘기가 더 낫겠어.":"응. 다른 얘기."
